typedef struct {
    int id;
    char name[16];
} Record;

// Allocate space for 10 records
size_t N = 10;
Record *ptr = (Record*) malloc(N * sizeof(Record));

// Validate allocation
if (ptr == NULL) return;

// Access using array notation
ptr[0].id = 101;

// Access using pointer arithmetic
(ptr + 5)->id = 105;

// Data validation/use
int check = ptr[5].id;

// Deallocate memory block
free(ptr);

// Reset pointer to prevent dangling pointer access
ptr = NULL;
